import { createReadStream } from 'node:fs';
import fs from 'node:fs/promises';
import path from 'node:path';
import { config } from '../../config/env.js';

// Keys are generated by the server (`<purpose>/<uuid>.<ext>`); anything else is refused
// so a key can never point outside the upload directory.
const KEY_PATTERN = /^[a-z]+\/[0-9a-f-]{36}\.[a-z0-9]{1,8}$/;

function resolveKey(key) {
  if (!KEY_PATTERN.test(key)) throw new Error(`Invalid storage key: ${key}`);
  // Read at call time: tests point the driver at a temporary directory.
  const root = path.resolve(config.storage.localDir);
  const target = path.resolve(root, key);
  if (!target.startsWith(root + path.sep)) throw new Error(`Invalid storage key: ${key}`);
  return target;
}

/** Stores files on the local disk. Development only: PaaS disks are wiped on redeploy. */
export const localStorage = {
  name: 'local',

  async put(key, buffer) {
    const target = resolveKey(key);
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.writeFile(target, buffer, { flag: 'wx' });
  },

  /** Size in bytes, or null when the file is missing. */
  async size(key) {
    try {
      return (await fs.stat(resolveKey(key))).size;
    } catch (error) {
      if (error.code === 'ENOENT') return null;
      throw error;
    }
  },

  createReadStream(key) {
    return createReadStream(resolveKey(key));
  },

  async remove(key) {
    await fs.rm(resolveKey(key), { force: true });
  },
};
